// setup body — receives ctx; runs on every enable (idempotent).
var badge = document.createElement('span');
badge.className = 'my-feature-badge';
badge.textContent = ctx.api.data.listCards().length + ' cards';
// tracked: auto-removed on suspend/delete
ctx.api.ui.inject('.header', badge, 'append');

// keep the count fresh
ctx.api.data.onUpdate(function () {
  badge.textContent = ctx.api.data.listCards().length + ' cards';
});

ctx.logger.info('my-feature ready');
